INSERT INTO public.notifications (id, user_id, title, body, link, priority, category, ref_key, read_at, created_at) VALUES ('06fae7da-be6e-447a-a92b-599e1b624b16', '0dcc787d-0670-4356-86b5-ec55c9311e60', '[ĐATN] Kế hoạch tổng quan – HKI 2026', 'Chào Nguyễn Xuân Trường, Nhà trường thông báo kế hoạch tổng quan quá trình thực hiện đồ án tốt nghiệp của HKI 2026, học kỳ 1, năm học 2026-2027. Các mốc thực hiện đồ án tốt nghiệp STT Nội dung thực hiện Thời gian Ghi chú / Biểu mẫu 1 Sinh viên nộp đề cương 01/01/2026 00:00 – 15/01/2026 23:59 2 Khoa kiểm tra và phản hồi đề cương 16/01/2026 00:00 – 18/01/2026 23:59 3 Sinh viên hoàn thiện đề cương theo phản hồi 19/01/2026 00:00 – 24/01/2026 23:59 4 Giảng viên xác nhận đề cương 25/01/2026 00:00 – 27/01/2026 23:59 5 Sinh viên nộp đề cương đã xác nhận 28/01/2026 00:00 – 29/01/2026 23:59 6 Khoa duyệt đề cương chính thức 30/01/2026 00:00 – 31/01/2026 23:59 7 Sinh viên xác nhận đăng ký giảng viên hướng dẫn 01/02/2026 00:00 – 05/02/2026 23:59 8 Giảng viên xác nhận hướng dẫn ĐATN 06/02/2026 00:00 – 08/02/2026 23:59 9 Sinh viên nộp báo cáo giữa kỳ 09/03/2026 00:00 – 15/03/2026 23:59 10 Giảng viên phản hồi báo cáo giữa kỳ 16/03/2026 00:00 – 20/03/2026 23:59 11 Sinh viên nộp báo cáo đồ án cho GVHD 01/04/2026 00:00 – 10/04/2026 23:59 12 GVHD nhận xét báo cáo đồ án 11/04/2026 00:00 – 15/04/2026 23:59 13 Sinh viên nộp báo cáo cho Hội đồng 16/04/2026 00:00 – 20/04/2026 23:59 14 Hội đồng tiếp nhận hồ sơ bảo vệ 21/04/2026 00:00 – 24/04/2026 23:59 15 Khoa công bố lịch bảo vệ 25/04/2026 00:00 – 28/04/2026 23:59 Lưu ý thực hiện Sinh viên theo dõi đầy đủ các mốc và hoàn thành hồ sơ đúng thời hạn trên hệ thống. Chủ động trao đổi với giảng viên hướng dẫn trong quá trình thực hiện đồ án. Các mốc chưa thiết lập sẽ được thông báo bổ sung khi kế hoạch cập nhật. Truy cập hệ thống: http://localhost:5173/dashboard Trân trọng, Ban quản lý đồ án tốt nghiệp', '/dashboard', 'NORMAL', 'CAMPAIGN', '52794314-3c72-49e7-9089-8b92cc23c766:campaign:CAMPAIGN_5e790a5d-f01b-4e7c-8482-ef919a13f36f', '2026-10-24 10:35:56.384507+07', '2026-10-24 01:33:12.659202+07') ON CONFLICT DO NOTHING;
