INSERT INTO public.round_mail_campaigns (id, round_id, subject, message, scheduled_at, status, recipient_count, created_at, queued_at, audience, step_key, priority, cc, bcc, created_by) VALUES ('665a762b-10b8-464a-9c9a-0b7347e2bafb', '52794314-3c72-49e7-9089-8b92cc23c766', 'Test', 'Chào các bạn sinh viên,
Khoa KH&KTTT chuyển đến các bạn kế hoạch thực hiện Đồ án tốt nghiệp hệ Liên thông và Văn bằng 2 ở HKI, NH 2026 - 2027 như sau:
KẾ HOẠCH THỰC HIỆN ĐỒ ÁN TỐT NGHIỆP
HỌC KỲ I NĂM HỌC 2026 - 2027
STT	NỘI DUNG THỰC HIỆN	THỜI GIAN	GHI CHÚ
1	SV nộp đề cương qua FORM	KTTT_ĐATN_DC_HKI_26-27	31/08/2026-05/09/2026	Mẫu đề cương
2
Khoa kiểm duyệt đề cương	09-13/09/2026	
Sinh viên chỉnh sửa theo yêu cầu và nộp lại đề cương và giải trình chỉnh sửa theo FORM
ĐK_KTTT_ĐATN_HCDC_HK1_26-27
15-20/09/2026
Nộp ONL theo form (bản nộp cần có đủ chữ ký của GVHD và SV)
Mẫu giải trình chỉnh sửa
3	Sinh viên triển khai các nội dung ĐATN	21/09/2026	
4	Sinh viên thực hiện báo cáo giữa kỳ với GVHD	09-15/11/2026	Tại thời điểm này SV có thể đổi tên đề tài
ĐATN_Mau_don_xin_doi_ten_de_tai_datn.docx
5
Sinh viên hoàn tất Đồ án Tốt nghiệp.
(Chỉnh sửa Báo cáo, hình thức trình bày)	21-27/12/2026	Biểu mẫu hướng dẫn hình thức trình bày
mẫu báo cáo
SV nộp báo cáo ĐATN qua form	CK_KTTT_ĐATN_BC_HKI_26-27	28-30/12/2026	
Khoa kiểm tra mức độ trùng lắp đồ án của SV	04-06/01/2027	
SV thực hiện chỉnh sửa nếu không đáp ứng tỷ lệ trùng lắp	08-11/01/2027	
Tổ chức bảo vệ ĐATN (01 buổi)	Từ 12 đến 15/01/2027	Dự kiến
SV thực hiện hiệu chỉnh sau bảo vệ, nộp lên hệ thống daa và nhờ GVHD xét duyệt		Hướng dẫn nộp báo cáo lên hệ thống
Lưu ý: Thời gian từ báo cáo giữa kỳ đến báo cáo trước Hội đồng có thể có sự điều chỉnh từ 01 - 02 tuần.
Lưu ý: 
- Hiện tại Khoa thực hiện thu thập thông tin đề cương do đó các bạn SV lưu ý thời gian nộp đề cương hết ngày 06/09/2026  (nội dung số 01 trong kế hoạch).
- Các SV chưa có đề tài/chưa có giảng viên hướng dẫn thì cần CHỦ ĐỘNG liên hệ các giảng viên theo danh sách đề tài dự kiến.
- Các email liên quan đến Đồ án tốt nghiệp các bạn vui lòng trao đổi tại email này cho đến khi hoàn thành Đồ án tốt nghiệp.
Chúc các bạn nghỉ lễ vui vẻ và hoàn thành tốt Đồ án tốt nghiệp.
Trân trọng./.
Nguyễn Thị Hoài - Thư ký Khoa,
Khoa Khoa học và Kỹ thuật Thông tin.', '2026-10-24 01:06:30.528911+07', 'QUEUED', 1, '2026-10-24 01:06:30.528817+07', '2026-10-24 01:06:30.528817+07', 'STUDENT', NULL, 'HIGH', NULL, NULL, '1c07203c-a430-4a5c-ab55-7667590bd528') ON CONFLICT DO NOTHING;
INSERT INTO public.round_mail_campaigns (id, round_id, subject, message, scheduled_at, status, recipient_count, created_at, queued_at, audience, step_key, priority, cc, bcc, created_by) VALUES ('5e790a5d-f01b-4e7c-8482-ef919a13f36f', '52794314-3c72-49e7-9089-8b92cc23c766', '[ĐATN] Kế hoạch tổng quan – HKI 2026', '<p>Chào {{tenNguoiNhan}},</p><p>Nhà trường thông báo kế hoạch tổng quan quá trình thực hiện đồ án tốt nghiệp của <strong>{{tenDot}}</strong>, học kỳ 1, năm học 2026-2027.</p><h2>Các mốc thực hiện đồ án tốt nghiệp</h2><table style="min-width: 100px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th><p>STT</p></th><th><p>Nội dung thực hiện</p></th><th><p>Thời gian</p></th><th><p>Ghi chú / Biểu mẫu</p></th></tr><tr><td><p>1</p></td><td><p>Sinh viên nộp đề cương</p></td><td><p>01/01/2026 00:00 – 15/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>2</p></td><td><p>Khoa kiểm tra và phản hồi đề cương</p></td><td><p>16/01/2026 00:00 – 18/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>3</p></td><td><p>Sinh viên hoàn thiện đề cương theo phản hồi</p></td><td><p>19/01/2026 00:00 – 24/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>4</p></td><td><p>Giảng viên xác nhận đề cương</p></td><td><p>25/01/2026 00:00 – 27/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>5</p></td><td><p>Sinh viên nộp đề cương đã xác nhận</p></td><td><p>28/01/2026 00:00 – 29/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>6</p></td><td><p>Khoa duyệt đề cương chính thức</p></td><td><p>30/01/2026 00:00 – 31/01/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>7</p></td><td><p>Sinh viên xác nhận đăng ký giảng viên hướng dẫn</p></td><td><p>01/02/2026 00:00 – 05/02/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>8</p></td><td><p>Giảng viên xác nhận hướng dẫn ĐATN</p></td><td><p>06/02/2026 00:00 – 08/02/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>9</p></td><td><p>Sinh viên nộp báo cáo giữa kỳ</p></td><td><p>09/03/2026 00:00 – 15/03/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>10</p></td><td><p>Giảng viên phản hồi báo cáo giữa kỳ</p></td><td><p>16/03/2026 00:00 – 20/03/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>11</p></td><td><p>Sinh viên nộp báo cáo đồ án cho GVHD</p></td><td><p>01/04/2026 00:00 – 10/04/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>12</p></td><td><p>GVHD nhận xét báo cáo đồ án</p></td><td><p>11/04/2026 00:00 – 15/04/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>13</p></td><td><p>Sinh viên nộp báo cáo cho Hội đồng</p></td><td><p>16/04/2026 00:00 – 20/04/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>14</p></td><td><p>Hội đồng tiếp nhận hồ sơ bảo vệ</p></td><td><p>21/04/2026 00:00 – 24/04/2026 23:59</p></td><td><p></p></td></tr><tr><td><p>15</p></td><td><p>Khoa công bố lịch bảo vệ</p></td><td><p>25/04/2026 00:00 – 28/04/2026 23:59</p></td><td><p></p></td></tr></tbody></table><h2>Lưu ý thực hiện</h2><ul><li><p>Sinh viên theo dõi đầy đủ các mốc và hoàn thành hồ sơ đúng thời hạn trên hệ thống.</p></li><li><p>Chủ động trao đổi với giảng viên hướng dẫn trong quá trình thực hiện đồ án.</p></li><li><p>Các mốc chưa thiết lập sẽ được thông báo bổ sung khi kế hoạch cập nhật.</p></li></ul><p>Truy cập hệ thống: {{link}}</p><p>Trân trọng,<br>Ban quản lý đồ án tốt nghiệp</p>', '2026-10-24 01:33:12.659604+07', 'QUEUED', 1, '2026-10-24 01:33:12.659202+07', '2026-10-24 01:33:12.659202+07', 'STUDENT', NULL, 'NORMAL', NULL, NULL, '1c07203c-a430-4a5c-ab55-7667590bd528') ON CONFLICT DO NOTHING;
